namespace sv_b086c06165d2409ababc03dd8b455fde.Services;

public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } = new List<(string, string)>
    {
        ("WH-001", "Warehouse A — Main Distribution"),
        ("WH-002", "Warehouse B — East Region"),
        ("WH-003", "Warehouse C — West Region"),
        ("WH-004", "Warehouse D — Returns Processing")
    };
}

namespace sv_b086c06165d2409ababc03dd8b455fde.Services;

public class InventoryAlertService
{
    private readonly Random _random = new();
    private int _lastCount;

    public int LastKnownCount => _lastCount;

    public event Action? OnAlertCountChanged;

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate a database query with a random count influenced by warehouse
        var seed = warehouseId.GetHashCode() ^ Environment.TickCount;
        var count = Random.Shared.Next(0, 16);
        return Task.FromResult(count);
    }

    public void PublishNewCount(int count)
    {
        _lastCount = count;
        OnAlertCountChanged?.Invoke();
    }
}

