@code {
    private Timer? _pollingTimer;
    private DateTime? _lastPollTime;
    private readonly List<PollEntry> _pollHistory = new();

    private string CurrentWarehouseName =>
        WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
        ?? "Unknown";

    private string AlertCardClass => AlertService.LastKnownCount switch
    {
        > 10 => "border-danger",
        > 5 => "border-warning",
        _ => ""
    };

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertDataChanged;

        // Start polling every 10 seconds
        _pollingTimer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
    }

    private void OnWarehouseChanged()
    {
        // Immediately poll when warehouse changes
        _ = PollAsync();
        InvokeAsync(StateHasChanged);
    }

    private void OnAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void PollCallback(object? state)
    {
        _ = PollAsync();
    }

    private async Task PollAsync()
    {
        var warehouseId = WarehouseState.CurrentWarehouseId;
        var count = await AlertService.GetLowStockCountAsync(warehouseId);
        _lastPollTime = DateTime.Now;

        _pollHistory.Add(new PollEntry(DateTime.Now, warehouseId, count));
        if (_pollHistory.Count > 50) _pollHistory.RemoveAt(0);

        // Publish to ALL subscribers (sidebar badge, other components)
        AlertService.PublishNewCount(count);
    }

    private static string GetBadgeClass(int count) => count switch
    {
        > 10 => "bg-danger",
        > 5 => "bg-warning text-dark",
        > 0 => "bg-info text-dark",
        _ => "bg-secondary"
    };

    public void Dispose()
    {
        _pollingTimer?.Dispose();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertDataChanged;
    }

    private record PollEntry(DateTime Time, string WarehouseId, int Count);
}

